#include <stdio.h>
struct Node {
    int val;
    struct Node *next;
};
int main() {
    struct Node c = {5, NULL};
    struct Node b = {7, &c};
    struct Node a = {11, &b};
    int sum = 0;
    for (struct Node *p = &a; p != NULL; p = p->next)
        sum = sum * 3 + p->val;
    printf("%d", (sum ^ 42) + 100);
    return 0;
}

